    (7, $hq$KHỐI 7 · ĐỘI TRƯỞNG$hq$, $hq$Đội trưởng$hq$, $hq$Thông hiểu$hq$, $hq$Kháng chiến lần thứ hai chống quân Nguyên (1285)$hq$, $hq$Sắp xếp sự kiện, chỉ trên bản đồ$hq$, $hq$Nội dung chính của Lịch sử 7 (chương trình 2018).$hq$, $hq$Lên bậc Thám hoa · thẻ Trần Quốc Toản, Trần Quang Khải, Trần Nhật Duật$hq$),
    (8, $hq$KHỐI 8 · TƯỚNG QUÂN$hq$, $hq$Tướng quân$hq$, $hq$Vận dụng$hq$, $hq$Kháng chiến lần thứ ba chống quân Nguyên (1287–1288)$hq$, $hq$Đọc tư liệu, xử lý tình huống$hq$, $hq$Phần mở rộng, ngoại khóa: vận dụng kiến thức Lịch sử 7.$hq$, $hq$Lên bậc Bảng nhãn · thẻ huyền thoại Trần Hưng Đạo · khung “Sóng Bạch Đằng”$hq$),
    (9, $hq$KHỐI 9 · NGUYÊN SOÁI$hq$, $hq$Nguyên soái$hq$, $hq$Vận dụng cao$hq$, $hq$Tổng kết: Hào khí Đông A qua ba lần kháng chiến$hq$, $hq$Lập bảng so sánh, tranh biện$hq$, $hq$Phần mở rộng, ngoại khóa: tổng hợp, so sánh, không thêm sự kiện mới.$hq$, $hq$Đủ sao cả bốn khối → đỗ Trạng nguyên · khung “Hoa sen vàng” · giao diện Hoàng thành$hq$)
ON CONFLICT (grade) DO NOTHING;

-- ---------------------------------------------------------------------- thẻ Binh thư đã nhặt ở bước Thám sử
ALTER TABLE public.hk_saga_progress ADD COLUMN IF NOT EXISTS lore TEXT[] NOT NULL DEFAULT '{}';
-- chặng đã học xong trước đây: coi như đã nhặt đủ thẻ của chặng đó (bộ sưu tập Binh thư phản ánh đúng những gì em đã học)
UPDATE public.hk_saga_progress p SET lore = ARRAY(SELECT c->>'id' FROM public.hk_saga_stages s, jsonb_array_elements(s.content->'cards') c WHERE s.id = p.stage_id)
    WHERE p.lesson_done_at IS NOT NULL AND cardinality(p.lore) = 0;

-- ---------------------------------------------------------------------- sổ vàng và nhiệm vụ
-- answer: đúng một câu (+2 vàng); star: mỗi sao trận đánh (+10 vàng); streak: mốc chuỗi ngày 3 / 14 ngày (+30 / +200 vàng)
ALTER TABLE public.hk_gold_ledger DROP CONSTRAINT IF EXISTS hk_gold_ledger_reason_check;
ALTER TABLE public.hk_gold_ledger ADD CONSTRAINT hk_gold_ledger_reason_check CHECK (reason IN ('node', 'quest', 'goal', 'gift', 'level', 'card', 'shop', 'contest', 'badge', 'battle', 'minigame', 'assignment', 'teacher', 'chest', 'answer', 'star', 'streak'));
ALTER TABLE public.hk_quest_templates DROP CONSTRAINT IF EXISTS hk_quest_templates_metric_check;
ALTER TABLE public.hk_quest_templates ADD CONSTRAINT hk_quest_templates_metric_check CHECK (metric IN ('correct_answers', 'nodes_completed', 'battles_completed', 'lessons_completed', 'xp_earned', 'perfect_quizzes', 'lore_collected', 'ai_questions'));
-- ba nhiệm vụ hằng ngày của bản vẽ (mẫu hệ thống, school_id rỗng – migration 039): trả lời đúng 10 câu, nhặt 2 thẻ Binh thư, hỏi Tiểu Tướng 1 câu;
-- các nhiệm vụ ngày khác của mẫu hệ thống tạm tắt (không xóa; nhiệm vụ tuần và nhiệm vụ riêng của trường giữ nguyên)
UPDATE public.hk_quest_templates SET reward_xp = 20, reward_gold = 20, sort_order = 1 WHERE code = 'ngay-10-cau-dung' AND school_id IS NULL;
INSERT INTO public.hk_quest_templates (code, period, title, metric, target, reward_xp, reward_gold, sort_order) VALUES
    ('ngay-2-the-binh-thu', 'daily', 'Thu thập 2 thẻ Binh thư', 'lore_collected', 2, 20, 30, 2),
    ('ngay-hoi-tieu-tuong', 'daily', 'Hỏi Tiểu Tướng 1 câu về sử Trần', 'ai_questions', 1, 20, 10, 3)
ON CONFLICT (code) WHERE school_id IS NULL DO NOTHING;
UPDATE public.hk_quest_templates SET is_active = false WHERE school_id IS NULL AND period = 'daily' AND code NOT IN ('ngay-10-cau-dung', 'ngay-2-the-binh-thu', 'ngay-hoi-tieu-tuong');

-- ---------------------------------------------------------------------- thứ tự chặng: Bạch Đằng 938 đứng đầu, bốn chặng Khối 9 ở cuối
-- dời tạm sang 51–63 rồi về 2–14 (thứ tự phải nằm trong 1–99 và không trùng ở mọi bước)
UPDATE public.hk_saga_stages SET position = position + 50 WHERE position < 50 AND code IN ($hq$binh-le-nguyen$hq$, $hq$vuon-khong-nha-trong$hq$, $hq$dong-bo-dau$hq$, $hq$binh-than$hq$, $hq$dien-hong$hq$, $hq$rut-lui-1285$hq$, $hq$ham-tu$hq$, $hq$chuong-duong$hq$, $hq$tay-ket$hq$, $hq$chuan-bi-1287$hq$, $hq$van-don$hq$, $hq$van-kiep-1288$hq$, $hq$bach-dang$hq$);
UPDATE public.hk_saga_stages SET position = position - 49 WHERE position > 50;

-- ---------------------------------------------------------------------- thẻ nhân vật mới
INSERT INTO public.hk_saga_cards (code, name, title, rarity, years, intro, role_text, quote, quote_source, source, source_url, portrait, sort_order) VALUES
    ($hq$ngo-quyen$hq$, $hq$Ngô Quyền$hq$, $hq$Tiền Ngô Vương$hq$, $hq$epic$hq$, $hq$898 – 944$hq$, $hq$Người Đường Lâm, con rể và là tướng của Dương Đình Nghệ. Năm 939 ông xưng vương, đóng đô ở Cổ Loa, mở đầu nhà Ngô.$hq$, $hq$Năm 938 đánh tan thủy quân Nam Hán trên sông Bạch Đằng bằng bãi cọc nhọn và con nước thủy triều, chấm dứt hơn một nghìn năm Bắc thuộc.$hq$, NULL, NULL, $hq$Wikipedia tiếng Việt, bài “Ngô Quyền” và “Trận Bạch Đằng (938)”$hq$, $hq$https://vi.wikipedia.org/wiki/Ng%C3%B4_Quy%E1%BB%81n$hq$, $hq$ngo-quyen$hq$, 0)
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- Khối 6 · Bạch Đằng 938 (Cuối năm 938)
INSERT INTO public.hk_saga_stages (code, campaign_no, grade, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$bach-dang-938$hq$, NULL, 6, 1, $hq$Bạch Đằng 938$hq$, $hq$Sông Bạch Đằng (Quảng Ninh – Hải Phòng)$hq$, $hq$Cuối năm 938$hq$, $hq$battle$hq$, $hq$waves$hq$, $hq$Ngô Quyền cắm cọc nhọn dưới lòng sông Bạch Đằng, nhử thuyền Nam Hán vào lúc nước triều còn cao rồi đánh khi triều rút. Nhà Trần dùng lại bài học này năm 1288.$hq$, 0.5, 0.5, NULL, NULL, NULL, 70, 100, 30, $hq$ngo-quyen$hq$, NULL,
     $hq${"objectives":[{"id":"o1","text":"Trình bày được cách Ngô Quyền dùng bãi cọc và thủy triều để đánh thắng quân Nam Hán năm 938."},{"id":"o2","text":"Nêu được ý nghĩa của chiến thắng Bạch Đằng năm 938 và mối liên hệ với trận Bạch Đằng năm 1288."}],"cards":[{"id":"c1","kind":"why","title":"Giặc lấy cớ cứu Kiều Công Tiễn","body":"Cuối năm 937, Kiều Công Tiễn giết Dương Đình Nghệ để cướp quyền rồi sai người mang vàng bạc sang cầu cứu nhà Nam Hán. Vua Nam Hán Lưu Cung nhân cơ hội sai con là Lưu Hoằng Tháo đem quân thủy sang đánh Tĩnh Hải quân.","facts":[{"label":"Chỉ huy giặc","value":"Lưu Hoằng Tháo"},{"label":"Quân Nam Hán","value":"Khoảng 2 vạn"}],"objective":"o1","source":"w938","art":"envoy"},{"id":"c2","kind":"how","title":"Diệt kẻ phản trước","body":"Ngô Quyền đem quân từ Ái Châu ra Bắc, tiến tới thành Đại La. Kiều Công Tiễn bị cô lập, không chống nổi và bị giết khi quân Nam Hán còn chưa tới biên giới.","facts":[{"label":"Nơi diệt Kiều Công Tiễn","value":"Thành Đại La"}],"objective":"o1","source":"w938","art":"swords"},{"id":"c3","kind":"where","title":"Lòng sông Bạch Đằng","body":"Sông Bạch Đằng (nay thuộc Quảng Yên, Quảng Ninh và Thủy Nguyên, Hải Phòng) là cửa ngõ đường thủy từ biển vào. Nước triều ở đây lên xuống mạnh. Ngô Quyền cho cắm cọc nhọn dưới lòng sông; khi triều lên, bãi cọc chìm khuất dưới nước.","facts":[{"label":"Điều then chốt","value":"Thủy triều lên – xuống"}],"objective":"o1","source":"w938","art":"river"},{"id":"c4","kind":"when","title":"Nhử lúc triều cao, đánh lúc triều rút","body":"Thấy thuyền ta nhẹ, quân ít, thuyền Nam Hán hùng hổ tiến vào cửa sông. Ngô Quyền cho quân bỏ chạy lên thượng lưu. Đợi nước triều rút, quân ta mới đổ ra đánh: thuyền lớn của giặc mắc cạn, bị cọc đâm thủng gần hết.","facts":[{"label":"Nhử giặc","value":"Khi nước triều còn cao"},{"label":"Phản công","value":"Khi nước triều rút"}],"objective":"o1","source":"w938","art":"boat"},{"id":"c5","kind":"why","title":"Chấm dứt Bắc thuộc","body":"Lưu Hoằng Tháo tử trận cùng hơn một nửa quân sĩ; vua Nam Hán phải rút quân. Năm 939 Ngô Quyền xưng vương, đóng đô ở Cổ Loa, chấm dứt hơn một nghìn năm Bắc thuộc. Năm 1288, nhà Trần lại dùng bãi cọc và con nước trên chính dòng sông này.","facts":[{"label":"Năm 939","value":"Ngô Quyền xưng vương"},{"label":"Kinh đô","value":"Cổ Loa"}],"objective":"o2","source":"w938","art":"star"}],"sources":[{"key":"w938","title":"Trận Bạch Đằng (938)","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư)","url":"https://vi.wikipedia.org/wiki/Tr%E1%BA%ADn_B%E1%BA%A1ch_%C4%90%E1%BA%B1ng_(938)","note":"Các nguồn chép khác nhau về quân số của quân ta; nội dung chỉ dùng phần các nguồn thống nhất."}],"explore":null,"battle":{"mode":"council","style":"command","title":"Hội đồng của Ngô Quyền","intro":"Quân Nam Hán sắp tới. Em cùng các tướng bàn từng việc: đánh ai trước, đánh ở đâu, nhử giặc lúc nào và phản công lúc nào.","cast":[{"id":"ngoquyen","name":"Ngô Quyền","role":"Người cầm quân","fictional":false},{"id":"tuong","name":"Viên tướng tham mưu","role":"Nhân vật hư cấu","fictional":true}],"meters":[{"id":"the","label":"Thế trận của ta","start":25,"win":70}],"rounds":[{"id":"r1","who":"Viên tướng tham mưu","ask":"Kiều Công Tiễn giết Dương Đình Nghệ rồi cầu cứu Nam Hán. Giặc ngoài sắp tới, kẻ phản ở trong. Ta nên làm gì trước?","label":"Đánh ai trước","history":"Ngô Quyền tiến ra thành Đại La, giết Kiều Công Tiễn khi quân Nam Hán còn chưa tới biên giới.","options":[{"id":"a","tag":"Thế trận","text":"Diệt Kiều Công Tiễn trước, để giặc mất người dẫn đường","say":null,"reply":"Phải! Trong yên thì ngoài mới đánh được.","score":2,"effect":{"the":15}},{"id":"b","tag":"Thế trận","text":"Đợi đánh xong giặc ngoài rồi mới tính","say":null,"reply":"Để kẻ phản ở sau lưng, giặc tới thì ta bị đánh cả hai mặt.","score":0,"effect":{"the":-5}},{"id":"c","tag":"Ngoại giao","text":"Sai sứ sang Nam Hán xin hòa","say":null,"reply":"Giặc đã có cớ sang đánh, xin hòa lúc này chỉ làm lòng quân rối.","score":0,"effect":{"the":-10}}]},{"id":"r2","who":"Ngô Quyền","ask":"Thuyền Nam Hán to và đông, thuyền ta nhẹ và ít. Theo em, ta nên đánh giặc ở đâu?","label":"Nơi đánh giặc","history":"Ngô Quyền cho cắm cọc nhọn dưới lòng sông Bạch Đằng, nơi nước triều lên xuống mạnh.","options":[{"id":"a","tag":"Địa thế","text":"Bày bãi cọc nhọn ở cửa sông Bạch Đằng","say":null,"reply":"Thuyền to vào đây mà vướng cọc thì không còn mạnh nữa.","score":2,"effect":{"the":20}},{"id":"b","tag":"Địa thế","text":"Ra biển chặn đánh thuyền lớn","say":null,"reply":"Ngoài biển thuyền giặc to, ta yếu thế hơn hẳn.","score":0,"effect":{"the":-10}},{"id":"c","tag":"Địa thế","text":"Rút về giữ thành Đại La","say":null,"reply":"Giữ thành thì an toàn nhưng để giặc vào sâu trong đất ta.","score":1,"effect":{"the":5}}]},{"id":"r3","who":"Viên tướng tham mưu","ask":"Bãi cọc đã đóng xong. Khi nào cho thuyền nhẹ ra nhử giặc vào cửa sông?","label":"Lúc nhử giặc","history":"Thấy thuyền ta nhẹ, quân ít, thuyền Nam Hán đuổi vào cửa sông; quân ta bỏ chạy lên thượng lưu (giặc phải vào bãi cọc khi nước triều còn cao, cọc chưa lộ).","options":[{"id":"a","tag":"Thời cơ","text":"Lúc nước triều còn cao, bãi cọc chìm khuất","say":null,"reply":"Giặc không thấy cọc nên cứ đuổi theo.","score":2,"effect":{"the":15}},{"id":"b","tag":"Thời cơ","text":"Lúc nước triều đã rút, cọc nhô lên","say":null,"reply":"Cọc lộ ra rồi, giặc thấy thì tránh xa ngay.","score":0,"effect":{"the":-10}},{"id":"c","tag":"Thời cơ","text":"Đánh luôn khi giặc vừa tới cửa biển","say":null,"reply":"Đánh sớm quá thì giặc chưa vào tới bãi cọc.","score":1,"effect":{"the":0}}]},{"id":"r4","who":"Ngô Quyền","ask":"Thuyền giặc đã đuổi vào khúc sông có cọc. Ta đổ quân ra đánh lúc nào?","label":"Lúc phản công","history":"Đợi nước triều rút, quân ta đổ ra đánh; thuyền lớn của giặc mắc cạn, bị cọc đâm thủng gần hết, Lưu Hoằng Tháo tử trận.","options":[{"id":"a","tag":"Thời cơ","text":"Khi nước triều rút, thuyền giặc mắc cọc","say":null,"reply":"Đúng lúc rồi! Thuyền giặc vỡ, quân giặc rối loạn.","score":2,"effect":{"the":15}},{"id":"b","tag":"Thời cơ","text":"Ngay lúc triều đang lên cao","say":null,"reply":"Nước còn cao, thuyền giặc vẫn đi lại được.","score":0,"effect":{"the":-10}},{"id":"c","tag":"Thời cơ","text":"Đợi tới hôm sau cho chắc","say":null,"reply":"Để lỡ con nước thì giặc thoát khỏi bãi cọc.","score":0,"effect":{"the":-10}}]}],"tips":["Đọc lại thẻ “Lòng sông Bạch Đằng” và “Nhử lúc triều cao, đánh lúc triều rút” trước khi chọn."],"win_text":"Thủy quân Nam Hán tan vỡ trên sông Bạch Đằng. Năm sau Ngô Quyền xưng vương, đất nước mở ra thời kỳ độc lập.","lose_text":"Kế đánh chưa thành. Hãy xem lại thứ tự: diệt kẻ phản, chọn nơi có bãi cọc, nhử giặc lúc triều cao, đánh khi triều rút."},"debrief":{"title":"Bạch Đằng 938: mưu giỏi mà đánh cũng giỏi","paragraphs":["Cuối năm 937, Kiều Công Tiễn giết Dương Đình Nghệ rồi cầu cứu nhà Nam Hán. Ngô Quyền đem quân ra Bắc, giết Kiều Công Tiễn ở thành Đại La trước khi quân Nam Hán do Lưu Hoằng Tháo chỉ huy kéo tới.","Cuối năm 938, Ngô Quyền cho cắm cọc nhọn dưới lòng sông Bạch Đằng. Thuyền Nam Hán đuổi theo thuyền nhẹ của ta vào cửa sông; đợi nước triều rút, quân ta đổ ra đánh, thuyền lớn của giặc mắc cạn và bị cọc đâm thủng gần hết. Lưu Hoằng Tháo tử trận.","Đại Việt sử ký toàn thư chép lời bàn khen Ngô Quyền “mưu giỏi mà đánh cũng giỏi”. Năm 939 ông xưng vương, đóng đô ở Cổ Loa, chấm dứt hơn một nghìn năm Bắc thuộc. Năm 1288, Trần Hưng Đạo lại dùng bãi cọc và con nước trên chính dòng sông này để đánh tan thủy quân Nguyên."],"sources":["w938"],"fiction":"Lời thoại trong hội đồng, các nhân vật không có tên trong sử (bô lão, tướng tá phụ) và mọi thanh chỉ số là phần sáng tạo của trò chơi. Dòng “Lịch sử” của mỗi lượt lấy từ nguồn ghi bên dưới; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."},"order":{"by":"Lời dẫn","text":"Năm 938, thủy quân Nam Hán sắp vượt biển vào cửa sông Bạch Đằng. Em theo Ngô Quyền dò xét dòng sông, nhặt đủ thẻ Binh thư rồi cùng hội đồng bàn kế đánh giặc."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 25/11/2026 (bốn chiến dịch theo khối): dữ kiện đối chiếu với các bài Wikipedia tiếng Việt “Trận Bạch Đằng (938)”, “Ngô Quyền” và các thẻ, tư liệu đã kiểm chứng của migration 066. Cần giáo viên Lịch sử rà soát lại.$hq$)
ON CONFLICT (code) DO NOTHING;
