    ($hq$g6-938-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Ai chỉ huy quân ta đánh thắng quân Nam Hán trên sông Bạch Đằng năm 938?$hq$, $hq${"options":[{"id":"a","text":"Ngô Quyền"},{"id":"b","text":"Trần Hưng Đạo"},{"id":"c","text":"Dương Đình Nghệ"},{"id":"d","text":"Kiều Công Tiễn"}],"correct":"a"}$hq$::jsonb, $hq$Ngô Quyền chỉ huy trận Bạch Đằng năm 938. Trần Hưng Đạo chỉ huy trận Bạch Đằng năm 1288; Dương Đình Nghệ bị Kiều Công Tiễn giết năm 937.$hq$, $hq$w938$hq$),
    ($hq$g6-938-p1$hq$, 2, $hq$pairs$hq$, $hq$practice$hq$, $hq$o1$hq$, $hq$Lật thẻ và ghép mỗi nhân vật với việc làm của người đó.$hq$, $hq${"left_label":"Nhân vật","right_label":"Việc làm","pairs":[{"id":"p1","left":"Ngô Quyền","right":"Cắm cọc nhọn trên sông Bạch Đằng"},{"id":"p2","left":"Kiều Công Tiễn","right":"Giết Dương Đình Nghệ, cầu cứu Nam Hán"},{"id":"p3","left":"Lưu Hoằng Tháo","right":"Chỉ huy thủy quân Nam Hán, tử trận"},{"id":"p4","left":"Lưu Cung","right":"Vua Nam Hán, sai con đem quân sang"}]}$hq$::jsonb, $hq$Kiều Công Tiễn phản chủ và cầu cứu Nam Hán; vua Nam Hán Lưu Cung sai con là Lưu Hoằng Tháo đem quân sang; Ngô Quyền đánh tan quân giặc trên sông Bạch Đằng.$hq$, $hq$w938$hq$),
    ($hq$g6-938-q2$hq$, 3, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Ngô Quyền cho quân đổ ra đánh thuyền giặc vào lúc nào?$hq$, $hq${"options":[{"id":"a","text":"Khi nước triều rút"},{"id":"b","text":"Khi nước triều vừa lên"},{"id":"c","text":"Ngay khi giặc tới cửa biển"},{"id":"d","text":"Lúc giặc đã lên bộ"}],"correct":"a"}$hq$::jsonb, $hq$Đợi nước triều rút, quân ta mới đổ ra đánh; thuyền lớn của giặc mắc cạn và bị cọc đâm thủng.$hq$, $hq$w938$hq$),
    ($hq$g6-938-s1$hq$, 4, $hq$sequence$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Xếp các sự việc theo đúng thứ tự thời gian.$hq$, $hq${"items":[{"id":"m1","text":"Kiều Công Tiễn giết Dương Đình Nghệ","when":"Cuối 937"},{"id":"m2","text":"Ngô Quyền giết Kiều Công Tiễn ở thành Đại La","when":"Năm 938"},{"id":"m3","text":"Thuyền Nam Hán vào cửa sông Bạch Đằng, vướng bãi cọc","when":"Cuối 938"},{"id":"m4","text":"Ngô Quyền xưng vương, đóng đô ở Cổ Loa","when":"Năm 939"}]}$hq$::jsonb, $hq$Diệt kẻ phản trước, rồi mới đánh tan quân Nam Hán; năm sau Ngô Quyền xưng vương ở Cổ Loa.$hq$, $hq$w938$hq$),
    ($hq$g6-938-t1$hq$, 5, $hq$tactic$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Em là người cầm quân, em chọn cách nào?$hq$, $hq${"situation":"Thuyền Nam Hán to và đông, thuyền của ta nhẹ và ít. Giặc sắp vượt biển vào cửa sông Bạch Đằng.","options":[{"id":"a","text":"Bày bãi cọc ở cửa sông nơi nước triều lên xuống mạnh","feedback":"Đúng với kế của Ngô Quyền: biến dòng sông thành cái bẫy cho thuyền lớn.","score":2},{"id":"b","text":"Ra biển chặn đánh ngay","feedback":"Ngoài biển thuyền to của giặc mạnh hơn thuyền nhẹ của ta.","score":0},{"id":"c","text":"Rút về giữ thành, chờ giặc lên bộ","feedback":"An toàn hơn nhưng để giặc vào sâu, không tận dụng được địa thế sông nước.","score":1}]}$hq$::jsonb, $hq$Ngô Quyền chọn đánh ở cửa sông Bạch Đằng, nơi ông có thể dùng bãi cọc và thủy triều.$hq$, $hq$w938$hq$),
    ($hq$g6-938-q3$hq$, 6, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Chiến thắng Bạch Đằng năm 938 có ý nghĩa gì?$hq$, $hq${"options":[{"id":"a","text":"Chấm dứt hơn một nghìn năm Bắc thuộc"},{"id":"b","text":"Đánh thắng quân Mông Cổ lần thứ nhất"},{"id":"c","text":"Mở đầu nhà Trần"},{"id":"d","text":"Dời đô ra Thăng Long"}],"correct":"a"}$hq$::jsonb, $hq$Sau chiến thắng, năm 939 Ngô Quyền xưng vương, đóng đô ở Cổ Loa, chấm dứt hơn một nghìn năm Bắc thuộc.$hq$, $hq$w938$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$bach-dang-938$hq$
