-- ---------------------------------------------------------------------- Khối 9 · So sánh ba lần kháng chiến (1258 – 1288)
INSERT INTO public.hk_saga_stages (code, campaign_no, grade, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$so-sanh-ba-lan$hq$, NULL, 9, 15, $hq$So sánh ba lần kháng chiến$hq$, $hq$Đại Việt$hq$, $hq$1258 – 1288$hq$, $hq$strategy$hq$, $hq$scroll$hq$, $hq$Lập bảng so sánh đối phương, người lãnh đạo, kế sách và trận quyết định của ba lần kháng chiến; tìm điều làm nên chiến thắng cả ba lần.$hq$, 0.5, 0.5, NULL, NULL, NULL, 70, 150, 50, NULL, NULL,
     $hq${"objectives":[{"id":"o1","text":"So sánh được đối phương, người lãnh đạo, kế sách và trận quyết định của ba lần kháng chiến."},{"id":"o2","text":"Rút ra được những điểm chung làm nên chiến thắng cả ba lần."}],"cards":[{"id":"c1","kind":"when","title":"Ba lần giặc tới","body":"Lần thứ nhất (1258): quân Mông Cổ từ Vân Nam tràn xuống. Lần thứ hai (1285) và lần thứ ba (cuối 1287 – 1288): quân Nguyên do Thoát Hoan chỉ huy; lần thứ ba có thêm thủy quân của Ô Mã Nhi và đoàn thuyền lương đi đường biển.","facts":[{"label":"Năm 1258","value":"Quân Mông Cổ"},{"label":"1285 và 1287–1288","value":"Quân Nguyên"}],"objective":"o1","source":"w3","art":"map"},{"id":"c2","kind":"who","title":"Những người cầm đầu","body":"Năm 1258, vua Trần Thái Tông đích thân cầm quân, Thái sư Trần Thủ Độ giữ vững ý chí kháng chiến. Năm 1285 và 1288, Thượng hoàng Trần Thánh Tông và vua Trần Nhân Tông lãnh đạo; Quốc công Tiết chế Trần Quốc Tuấn thống lĩnh toàn quân.","facts":[{"label":"Tổng chỉ huy 1285, 1288","value":"Trần Quốc Tuấn"}],"objective":"o1","source":"w2","art":"general"},{"id":"c3","kind":"how","title":"Kế sách lặp lại","body":"Cả ba lần, quân Trần đều tránh đối đầu khi giặc còn mạnh: rời kinh thành, làm “vườn không nhà trống”, không để lương thực cho giặc; đợi giặc mỏi mệt, thiếu lương mới phản công.","facts":[{"label":"Kế chung","value":"Vườn không nhà trống"}],"objective":"o2","source":"w2","art":"granary"},{"id":"c4","kind":"where","title":"Những trận quyết định","body":"Năm 1258: Đông Bộ Đầu (đêm 28/1/1258). Năm 1285: Hàm Tử, Chương Dương, Tây Kết (24/6/1285). Lần thứ ba: Vân Đồn (cuối 12/1287 – đầu 1/1288) và Bạch Đằng (9/4/1288).","facts":[{"label":"Trận cuối cùng","value":"Bạch Đằng, 9/4/1288"}],"objective":"o1","source":"w3","art":"swords"},{"id":"c5","kind":"why","title":"Vì sao ba lần đều thắng","body":"Cả nước đồng lòng (Bình Than, Diên Hồng), kế sách đúng (lui để giữ sức, đánh vào lương giặc, lợi dụng thủy triều) và những người cầm quân tài giỏi. Trần Hưng Đạo dặn vua: “Khoan thư sức dân để làm kế sâu rễ bền gốc, đó là thượng sách giữ nước vậy.”","facts":[{"label":"Bài học","value":"Khoan thư sức dân"}],"objective":"o2","source":"wthd","art":"crowd"}],"sources":[{"key":"w1","title":"Chiến tranh Nguyên Mông – Đại Việt lần 1","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_1","note":"Bản đồ gốc của bài: Chongquannguyenlan1.svg, tác giả Lưu Ly, phạm vi công cộng."},{"key":"w2","title":"Chiến tranh Nguyên Mông – Đại Việt lần 2","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử; Hà Văn Tấn – Phạm Thị Tâm)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_2","note":"Một số chi tiết các nguồn chép khác nhau; nội dung chỉ dùng phần các nguồn thống nhất."},{"key":"w3","title":"Chiến tranh Nguyên Mông – Đại Việt lần 3","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử, Khâm định Việt sử thông giám cương mục)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_3","note":null},{"key":"wthd","title":"Trần Hưng Đạo","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư)","url":"https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_H%C6%B0ng_%C4%90%E1%BA%A1o","note":null}],"explore":null,"battle":null,"debrief":{"title":"Ba lần kháng chiến, một hào khí","paragraphs":["Đối phương mỗi lần một mạnh hơn: quân Mông Cổ năm 1258, quân Nguyên năm 1285 và năm 1287–1288 với cả thủy quân và đoàn thuyền lương. Người lãnh đạo là các vua Trần, Thái sư Trần Thủ Độ (1258) và Quốc công Tiết chế Trần Quốc Tuấn (1285, 1288).","Kế sách lặp lại cả ba lần: tránh đối đầu khi giặc mạnh, rời kinh thành, không để lương cho giặc, rồi phản công khi giặc suy yếu. Trận quyết định là Đông Bộ Đầu (1258), Tây Kết, Chương Dương (1285), Vân Đồn và Bạch Đằng (1288).","Điểm chung làm nên chiến thắng là sự đồng lòng từ triều đình tới nhân dân, kế sách đúng và tài cầm quân; Trần Hưng Đạo tổng kết bằng lời dặn “khoan thư sức dân”."],"sources":["w1","w2","w3","wthd"],"fiction":"Chặng tổng kết này không thêm sự kiện mới; mọi dữ kiện lấy từ các chặng trước và nguồn ghi bên dưới."},"order":{"by":"Lời dẫn","text":"Em đã đi qua ba cuộc kháng chiến. Nay hội đồng giao em lập bảng so sánh: giặc là ai, ai cầm quân, ta dùng kế gì, trận nào quyết định."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 25/11/2026 (bốn chiến dịch theo khối): dữ kiện đối chiếu với các bài Wikipedia tiếng Việt “Trận Bạch Đằng (938)”, “Ngô Quyền” và các thẻ, tư liệu đã kiểm chứng của migration 066. Cần giáo viên Lịch sử rà soát lại.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$g9-ss-p1$hq$, 1, $hq$pairs$hq$, $hq$practice$hq$, $hq$o1$hq$, $hq$Lật thẻ và ghép mỗi mốc thời gian với sự kiện của nó.$hq$, $hq${"left_label":"Thời gian","right_label":"Sự kiện","pairs":[{"id":"p1","left":"Đêm 28/1/1258","right":"Đánh úp quân Mông Cổ ở Đông Bộ Đầu"},{"id":"p2","left":"Cuối năm 1282","right":"Hội nghị Bình Than"},{"id":"p3","left":"Đầu năm 1285","right":"Hội nghị Diên Hồng"},{"id":"p4","left":"24/6/1285","right":"Trận Tây Kết"},{"id":"p5","left":"9/4/1288","right":"Trận Bạch Đằng"}]}$hq$::jsonb, $hq$Năm mốc này nối ba cuộc kháng chiến: thắng Đông Bộ Đầu, hai hội nghị trước lần thứ hai, Tây Kết và Bạch Đằng.$hq$, $hq$w3$hq$),
    ($hq$g9-ss-p2$hq$, 2, $hq$pairs$hq$, $hq$practice$hq$, $hq$o1$hq$, $hq$Lật thẻ và ghép mỗi nhân vật với vai trò của người đó.$hq$, $hq${"left_label":"Nhân vật","right_label":"Vai trò","pairs":[{"id":"p1","left":"Trần Thủ Độ","right":"Thái sư, giữ ý chí kháng chiến năm 1258"},{"id":"p2","left":"Trần Quốc Tuấn","right":"Quốc công Tiết chế năm 1285 và 1288"},{"id":"p3","left":"Thoát Hoan","right":"Chỉ huy quân Nguyên lần hai và lần ba"},{"id":"p4","left":"Ô Mã Nhi","right":"Chỉ huy thủy quân Nguyên, bị bắt ở Bạch Đằng"}]}$hq$::jsonb, $hq$Trần Thủ Độ (1258), Trần Quốc Tuấn (1285, 1288) bên ta; Thoát Hoan và Ô Mã Nhi bên quân Nguyên.$hq$, $hq$w2$hq$),
    ($hq$g9-ss-s1$hq$, 3, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp các sự kiện của ba lần kháng chiến theo đúng thứ tự.$hq$, $hq${"items":[{"id":"m1","text":"Đánh úp quân Mông Cổ ở Đông Bộ Đầu","when":"1258"},{"id":"m2","text":"Hội nghị Bình Than","when":"Cuối 1282"},{"id":"m3","text":"Hội nghị Diên Hồng","when":"Đầu 1285"},{"id":"m4","text":"Trận Tây Kết","when":"24/6/1285"},{"id":"m5","text":"Trận Vân Đồn","when":"Cuối 1287 – đầu 1288"},{"id":"m6","text":"Trận Bạch Đằng","when":"9/4/1288"}]}$hq$::jsonb, $hq$Thứ tự đúng đi từ lần thứ nhất (1258), qua hai hội nghị và lần thứ hai (1285), tới lần thứ ba (Vân Đồn, Bạch Đằng 1288).$hq$, $hq$w3$hq$),
    ($hq$g9-ss-q1$hq$, 4, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Kế sách nào quân Trần dùng trong cả ba lần kháng chiến?$hq$, $hq${"options":[{"id":"a","text":"Rời kinh thành, làm “vườn không nhà trống” để giặc thiếu lương"},{"id":"b","text":"Đánh chặn giặc ở biên giới đến cùng"},{"id":"c","text":"Xây thành đá thật cao để cố thủ"},{"id":"d","text":"Nhờ nước khác đem quân sang giúp"}],"correct":"a"}$hq$::jsonb, $hq$Cả ba lần quân Trần đều tránh đối đầu khi giặc mạnh, rời kinh thành và không để lương thực cho giặc.$hq$, $hq$w2$hq$),
    ($hq$g9-ss-t1$hq$, 5, $hq$tactic$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Em tranh biện thế nào?$hq$, $hq${"situation":"Một bạn nói: “Năm 1288 quân Trần thắng chỉ nhờ may mắn có thủy triều.”","options":[{"id":"a","text":"Thủy triều chỉ là điều kiện; quân Trần thắng vì hiểu con nước, đóng cọc, nhử giặc đúng lúc và chặn cả đường bộ","feedback":"Đúng: con nước có sẵn, nhưng biết dùng nó mới là tài cầm quân.","score":2},{"id":"b","text":"Thủy triều quan trọng nhất, còn bãi cọc chỉ là phụ","feedback":"Chưa đủ: không có bãi cọc và kế nhử giặc thì thủy triều không làm thuyền giặc vỡ được.","score":1},{"id":"c","text":"Đúng vậy, đó chỉ là may mắn","feedback":"Chưa đúng: trận đánh được chuẩn bị rất kỹ, từ đóng cọc tới chặn đường rút của giặc.","score":0}]}$hq$::jsonb, $hq$Trần Hưng Đạo nghiên cứu kỹ con nước để bày trận cọc, cho quân khiêu chiến lúc triều lên và đánh khi triều rút.$hq$, $hq$wthd$hq$),
    ($hq$g9-ss-q2$hq$, 6, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Điểm mới của quân Nguyên trong lần thứ ba so với lần thứ hai là gì?$hq$, $hq${"options":[{"id":"a","text":"Có thêm thủy quân và đoàn thuyền lương đi đường biển"},{"id":"b","text":"Không vào được Thăng Long"},{"id":"c","text":"Đi từ Vân Nam tràn xuống"},{"id":"d","text":"Không có người chỉ huy"}],"correct":"a"}$hq$::jsonb, $hq$Lần thứ ba, quân Nguyên mang theo thủy quân của Ô Mã Nhi và đoàn thuyền lương đi đường biển; vì vậy trận Vân Đồn trở thành bước ngoặt.$hq$, $hq$w3$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$so-sanh-ba-lan$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- Khối 9 · Hội đồng Đại cục (1258 – 1288)
INSERT INTO public.hk_saga_stages (code, campaign_no, grade, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$hoi-dong-dai-cuc$hq$, NULL, 9, 16, $hq$Hội đồng Đại cục$hq$, $hq$Đại Việt$hq$, $hq$1258 – 1288$hq$, $hq$council$hq$, $hq$crown$hq$, $hq$Chế độ mới: em chỉ huy cả cuộc chiến qua năm quyết định lớn, từ năm 1258 tới trận Bạch Đằng 1288; giữ được lòng dân và lực lượng thì thắng.$hq$, 0.5, 0.5, NULL, NULL, $hq$so-sanh-ba-lan$hq$, 70, 150, 50, NULL, NULL,
     $hq${"objectives":[{"id":"o1","text":"Vận dụng được hiểu biết về ba lần kháng chiến để đưa ra quyết định ở những thời điểm then chốt."},{"id":"o2","text":"Giải thích được vì sao mỗi quyết định đúng của nhà Trần dẫn tới thắng lợi."}],"cards":[{"id":"c1","kind":"how","title":"Lui để giữ sức","body":"Sau trận Bình Lệ Nguyên (17/1/1258), vua Trần Thái Tông lui quân, giữ được thuyền và lực lượng chủ lực. Năm 1285, quân Trần lại rời Thăng Long; quân Nguyên vào thành chỉ thấy cung thất trống không.","facts":[{"label":"Giữ được","value":"Thuyền và chủ lực"}],"objective":"o2","source":"w1","art":"shield"},{"id":"c2","kind":"who","title":"Hỏi ý cả nước","body":"Cuối năm 1282, hội nghị Bình Than bàn kế đánh giặc. Đầu năm 1285, ở điện Diên Hồng, các bô lão “vạn người cùng nói như từ một miệng”: “Đánh!”.","facts":[{"label":"Hai hội nghị","value":"Bình Than, Diên Hồng"}],"objective":"o2","source":"w2","art":"crowd"},{"id":"c3","kind":"why","title":"Đánh vào lương giặc","body":"Cuối 1287 – đầu 1288, Trần Khánh Dư đánh tan đoàn thuyền lương của Trương Văn Hổ ở Vân Đồn. Mất lương, quân Nguyên rơi vào thế bị động.","facts":[{"label":"Người chỉ huy","value":"Trần Khánh Dư"}],"objective":"o2","source":"w3","art":"granary"},{"id":"c4","kind":"where","title":"Chặn đường rút","body":"Năm 1288, Thoát Hoan rút quân theo hai đường. Thủy quân Ô Mã Nhi bị tiêu diệt trên sông Bạch Đằng ngày 9/4/1288; cánh quân bộ bị chặn đánh trên đường về nước.","facts":[{"label":"Trận quyết chiến","value":"Bạch Đằng, 9/4/1288"}],"objective":"o1","source":"w3","art":"stakes"}],"sources":[{"key":"w1","title":"Chiến tranh Nguyên Mông – Đại Việt lần 1","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_1","note":"Bản đồ gốc của bài: Chongquannguyenlan1.svg, tác giả Lưu Ly, phạm vi công cộng."},{"key":"w2","title":"Chiến tranh Nguyên Mông – Đại Việt lần 2","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử; Hà Văn Tấn – Phạm Thị Tâm)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_2","note":"Một số chi tiết các nguồn chép khác nhau; nội dung chỉ dùng phần các nguồn thống nhất."},{"key":"w3","title":"Chiến tranh Nguyên Mông – Đại Việt lần 3","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử, Khâm định Việt sử thông giám cương mục)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_3","note":null}],"explore":null,"battle":{"mode":"council","style":"command","title":"Hội đồng Đại cục","intro":"Năm quyết định lớn của ba cuộc kháng chiến. Mỗi lựa chọn làm thay đổi lòng dân và lực lượng của ta; cuối cùng cả hai phải đủ mạnh để thắng.","cast":[{"id":"hoidong","name":"Hội đồng các tướng","role":"Nhân vật hư cấu","fictional":true}],"meters":[{"id":"dan","label":"Lòng dân","start":40,"win":70},{"id":"luc","label":"Lực lượng","start":40,"win":70}],"rounds":[{"id":"r1","who":"Hội đồng các tướng","ask":"Năm 1258, thua trận Bình Lệ Nguyên, kỵ binh Mông Cổ đang tiến về kinh thành. Ta làm gì?","label":"1258: khi giặc mạnh","history":"Vua Trần Thái Tông lui quân, giữ được thuyền và lực lượng chủ lực; mười ngày sau phản công ở Đông Bộ Đầu.","options":[{"id":"a","tag":"Kế sách","text":"Rời kinh thành, giữ thuyền và lực lượng","say":null,"reply":"Còn quân, còn thuyền thì còn ngày đánh lại.","score":2,"effect":{"luc":15}},{"id":"b","tag":"Kế sách","text":"Giữ Thăng Long đến người cuối cùng","say":null,"reply":"Dốc hết quân giữ thành lúc giặc mạnh là mất cả chủ lực.","score":0,"effect":{"dan":-5,"luc":-25}},{"id":"c","tag":"Kế sách","text":"Sang đất Tống lánh nạn","say":null,"reply":"Vua bỏ nước thì lòng dân tan rã.","score":0,"effect":{"dan":-25,"luc":-10}}]},{"id":"r2","who":"Hội đồng các tướng","ask":"Biết quân Nguyên chuẩn bị đánh lần thứ hai, triều đình nên làm gì?","label":"1282–1285: trước khi giặc sang","history":"Cuối 1282 họp hội nghị Bình Than; đầu 1285 các bô lão ở Diên Hồng đồng thanh hô “Đánh!”.","options":[{"id":"a","tag":"Đồng lòng","text":"Họp vương hầu ở Bình Than và hỏi ý bô lão ở Diên Hồng","say":null,"reply":"Từ triều đình tới làng xã đều một lòng.","score":2,"effect":{"dan":25,"luc":5}},{"id":"b","tag":"Đồng lòng","text":"Chỉ bàn trong triều, giữ kín với dân","say":null,"reply":"Kế hay nhưng dân chưa được cùng bàn.","score":1,"effect":{"dan":5}},{"id":"c","tag":"Ngoại giao","text":"Nộp cống thật nhiều để giặc thôi đánh","say":null,"reply":"Giặc đã quyết đánh, nộp cống chỉ làm ta yếu đi.","score":0,"effect":{"dan":-20}}]},{"id":"r3","who":"Hội đồng các tướng","ask":"Đầu năm 1285, quân Nguyên rất đông tràn xuống Thăng Long. Ta làm gì?","label":"1285: giặc tràn xuống","history":"Quân Trần cản giặc rồi rời kinh thành; quân Nguyên vào thành chỉ thấy cung thất trống không, càng ngày càng thiếu lương.","options":[{"id":"a","tag":"Kế sách","text":"Lui quân, cất giấu lương, chờ thời cơ phản công","say":null,"reply":"Giặc vào thành trống, ta giữ được sức.","score":2,"effect":{"dan":5,"luc":15}},{"id":"b","tag":"Kế sách","text":"Dồn hết quân giữ kinh thành","say":null,"reply":"Đối đầu khi giặc đang mạnh nhất thì thiệt hại lớn.","score":0,"effect":{"luc":-20}},{"id":"c","tag":"Ngoại giao","text":"Xin hàng để cứu dân","say":null,"reply":"Đầu hàng thì mất nước, dân càng khổ.","score":0,"effect":{"dan":-30}}]},{"id":"r4","who":"Hội đồng các tướng","ask":"Cuối 1287, quân Nguyên chở lương bằng một đoàn thuyền lớn trên biển. Ta làm gì?","label":"1287–1288: đường lương giặc","history":"Trần Khánh Dư đánh tan đoàn thuyền lương ở Vân Đồn; quân Nguyên từ đó thiếu lương.","options":[{"id":"a","tag":"Thế giặc","text":"Đánh tan đoàn thuyền lương ở Vân Đồn","say":null,"reply":"Giặc đông mà không có lương thì không đánh lâu được.","score":2,"effect":{"dan":5,"luc":10}},{"id":"b","tag":"Thế giặc","text":"Chỉ đánh thuyền chiến, bỏ qua thuyền lương","say":null,"reply":"Đánh được giặc nhưng chúng vẫn còn lương.","score":1,"effect":{"luc":3}},{"id":"c","tag":"Kế sách","text":"Bỏ qua, chỉ lo giữ kinh thành","say":null,"reply":"Giặc đủ lương thì sẽ đánh lâu dài.","score":0,"effect":{"luc":-10}}]},{"id":"r5","who":"Hội đồng các tướng","ask":"Đói và mệt, Thoát Hoan quyết định rút quân theo hai đường thủy và bộ. Ta làm gì?","label":"1288: giặc rút về","history":"Ngày 9/4/1288 thủy quân Nguyên bị tiêu diệt trên sông Bạch Đằng; cánh quân bộ bị chặn đánh trên đường rút.","options":[{"id":"a","tag":"Địa thế","text":"Bày trận cọc ở Bạch Đằng và chặn cả đường bộ","say":null,"reply":"Không để giặc lành lặn trở về rồi lại sang lần nữa.","score":2,"effect":{"dan":10,"luc":10}},{"id":"b","tag":"Địa thế","text":"Chỉ chặn đánh đường bộ","say":null,"reply":"Thủy quân giặc sẽ thoát ra biển.","score":1,"effect":{"luc":3}},{"id":"c","tag":"Kế sách","text":"Để giặc rút êm cho chóng hết chiến tranh","say":null,"reply":"Giặc còn lực lượng thì còn quay lại.","score":0,"effect":{"dan":-10}}]}],"tips":["Lòng dân và lực lượng đều phải đạt 70 trở lên ở lượt cuối.","Nhớ lại kế chung của cả ba lần: tránh giặc khi giặc mạnh, đánh khi giặc yếu."],"win_text":"Đại cục đã định: ba lần đánh thắng quân Mông – Nguyên. Lòng dân và lực lượng là gốc của chiến thắng.","lose_text":"Đại cục chưa vững. Hãy xem lại những lượt làm lòng dân hoặc lực lượng giảm mạnh."},"debrief":{"title":"Năm quyết định làm nên chiến thắng","paragraphs":["Năm 1258, vua Trần Thái Tông lui quân sau trận Bình Lệ Nguyên để giữ thuyền và chủ lực, rồi phản công ở Đông Bộ Đầu. Trước lần thứ hai, hội nghị Bình Than (cuối 1282) và Diên Hồng (đầu 1285) tập hợp sức mạnh cả nước.","Năm 1285, quân Trần lại rời kinh thành, để giặc vào thành trống và thiếu lương. Lần thứ ba, trận Vân Đồn đánh tan đoàn thuyền lương, rồi trận Bạch Đằng (9/4/1288) tiêu diệt thủy quân Nguyên khi giặc rút."],"sources":["w1","w2","w3"],"fiction":"Lời thoại trong hội đồng, các nhân vật không có tên trong sử (bô lão, tướng tá phụ) và mọi thanh chỉ số là phần sáng tạo của trò chơi. Dòng “Lịch sử” của mỗi lượt lấy từ nguồn ghi bên dưới; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."},"order":{"by":"Lời dẫn","text":"Hội đồng giao em quyền chỉ huy đại cục. Mỗi quyết định ảnh hưởng tới lòng dân và lực lượng của cả cuộc chiến."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 25/11/2026 (bốn chiến dịch theo khối): dữ kiện đối chiếu với các bài Wikipedia tiếng Việt “Trận Bạch Đằng (938)”, “Ngô Quyền” và các thẻ, tư liệu đã kiểm chứng của migration 066. Cần giáo viên Lịch sử rà soát lại.$hq$)
ON CONFLICT (code) DO NOTHING;
