    ($hq$g9-dc-q2$hq$, 2, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Hội nghị Diên Hồng có ý nghĩa gì đối với cuộc kháng chiến?$hq$, $hq${"options":[{"id":"a","text":"Tập hợp sự đồng lòng của nhân dân cả nước"},{"id":"b","text":"Chọn người kế vị ngai vàng"},{"id":"c","text":"Ký hòa ước với quân Nguyên"},{"id":"d","text":"Chia ruộng đất cho quân sĩ"}],"correct":"a"}$hq$::jsonb, $hq$Khi được hỏi nên hòa hay đánh, các bô lão đồng thanh “Đánh!”: cả nước một lòng kháng chiến.$hq$, $hq$w2$hq$),
    ($hq$g9-dc-t1$hq$, 3, $hq$tactic$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Em là tướng giữ vùng biển, em chọn cách nào?$hq$, $hq${"situation":"Cuối năm 1287, quân Nguyên chở lương bằng một đoàn thuyền lớn đi đường biển để nuôi đạo quân đông đảo.","options":[{"id":"a","text":"Đánh tan đoàn thuyền lương","feedback":"Đúng với trận Vân Đồn: mất lương, giặc rơi vào thế bị động.","score":2},{"id":"b","text":"Chỉ đánh thuyền chiến của giặc","feedback":"Có lợi nhưng giặc vẫn còn lương để đánh lâu.","score":1},{"id":"c","text":"Rút hết về giữ kinh thành","feedback":"Để giặc đủ lương là để chúng đánh lâu dài.","score":0}]}$hq$::jsonb, $hq$Trần Khánh Dư đánh tan đoàn thuyền lương của Trương Văn Hổ ở Vân Đồn; từ đó quân Nguyên thiếu lương.$hq$, $hq$w3$hq$),
    ($hq$g9-dc-s1$hq$, 4, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp các quyết định lớn theo đúng thứ tự.$hq$, $hq${"items":[{"id":"m1","text":"Lui quân sau trận Bình Lệ Nguyên","when":"1258"},{"id":"m2","text":"Họp hội nghị Bình Than","when":"Cuối 1282"},{"id":"m3","text":"Hỏi ý bô lão ở Diên Hồng","when":"Đầu 1285"},{"id":"m4","text":"Đánh đoàn thuyền lương ở Vân Đồn","when":"Cuối 1287 – đầu 1288"},{"id":"m5","text":"Bày trận cọc ở Bạch Đằng","when":"Tháng 4/1288"}]}$hq$::jsonb, $hq$Năm quyết định nối nhau từ năm 1258 tới trận Bạch Đằng năm 1288.$hq$, $hq$w3$hq$),
    ($hq$g9-dc-q3$hq$, 5, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Khi thế giặc mạnh, vì sao quân Trần thường chủ động lui quân?$hq$, $hq${"options":[{"id":"a","text":"Để bảo toàn lực lượng, kéo giặc vào thế thiếu lương rồi phản công"},{"id":"b","text":"Vì quân Trần không có vũ khí"},{"id":"c","text":"Vì vua Trần muốn giảng hòa"},{"id":"d","text":"Vì kinh thành Thăng Long quá nhỏ"}],"correct":"a"}$hq$::jsonb, $hq$Lui để giữ sức là kế lặp lại cả ba lần; giặc vào thành trống, thiếu lương, quân Trần phản công khi giặc suy yếu.$hq$, $hq$w2$hq$),
    ($hq$g9-dc-t2$hq$, 6, $hq$tactic$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Em là người chỉ huy, em chọn cách nào?$hq$, $hq${"situation":"Năm 1288 giặc cạn lương, quyết định rút về nước theo hai đường: thủy quân theo đường sông ra biển, quân bộ theo đường bộ.","options":[{"id":"a","text":"Đón đánh cả hai đường, bày trận cọc ở sông Bạch Đằng","feedback":"Đúng với kế của Trần Hưng Đạo: không để giặc lành lặn trở về.","score":2},{"id":"b","text":"Chỉ chặn đường bộ","feedback":"Thủy quân giặc sẽ theo đường sông ra biển mà thoát.","score":1},{"id":"c","text":"Để giặc rút êm","feedback":"Giặc còn lực lượng thì còn quay lại xâm lược.","score":0}]}$hq$::jsonb, $hq$Trần Hưng Đạo cho đón đánh cả hai đường; thủy quân Nguyên bị tiêu diệt ở Bạch Đằng ngày 9/4/1288.$hq$, $hq$w3$hq$)
