INSERT INTO public.hk_saga_stages (code, campaign_no, grade, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$tu-lieu-tranh-bien$hq$, NULL, 9, 17, $hq$Tư liệu gốc và tranh biện$hq$, $hq$Đại Việt sử ký toàn thư$hq$, $hq$1258 – 1288$hq$, $hq$prepare$hq$, $hq$scroll$hq$, $hq$Đọc những câu nói, câu thơ, đoạn sử được chép lại; phân biệt sử liệu với chuyện tương truyền và dùng nguồn khi tranh biện.$hq$, 0.5, 0.5, NULL, NULL, $hq$hoi-dong-dai-cuc$hq$, 70, 150, 50, NULL, NULL,
     $hq${"objectives":[{"id":"o1","text":"Đọc và giải thích được ý nghĩa của một số tư liệu gốc về ba lần kháng chiến."},{"id":"o2","text":"Phân biệt được sử liệu với chuyện tương truyền và biết dùng nguồn khi tranh biện."}],"cards":[{"id":"c1","kind":"who","title":"Lời Thái sư Trần Thủ Độ","body":"Trên sông Thiên Mạc năm 1258, khi có người khuyên vua sang lánh đất Tống, Thái sư Trần Thủ Độ tâu: “Đầu thần chưa rơi xuống đất, bệ hạ đừng lo gì khác.”","facts":[{"label":"Nguồn","value":"Đại Việt sử ký toàn thư"}],"objective":"o1","source":"w1","art":"scroll"},{"id":"c2","kind":"when","title":"Tiếng hô ở Diên Hồng","body":"Đầu năm 1285, khi Thượng hoàng hỏi có nên đánh lại quân Nguyên hay không, các bô lão “vạn người cùng nói như từ một miệng”: “Đánh!”.","facts":[{"label":"Nguồn","value":"Đại Việt sử ký toàn thư"}],"objective":"o1","source":"w2","art":"crowd"},{"id":"c3","kind":"how","title":"Toàn thư chép trận Bạch Đằng","body":"“Nhân lúc nước triều lên, Vương cho quân khiêu chiến rồi giả thua chạy, giặc đuổi theo, quân ta cố sức đánh lại. Nước triều xuống, thuyền giặc vướng cọc hết.” (“Vương” là Hưng Đạo vương Trần Quốc Tuấn.)","facts":[{"label":"Nguồn","value":"Đại Việt sử ký toàn thư, quyển 5"}],"objective":"o1","source":"manhghep","art":"boat"},{"id":"c4","kind":"why","title":"Tương truyền hay sử liệu?","body":"Năm 1285, Thoát Hoan bị chặn đánh khi rút chạy. Chuyện ông phải chui vào ống đồng để trốn về nước chỉ là “tương truyền”: khi kể lại phải nói rõ như vậy, không viết như một sự thật chắc chắn.","facts":[{"label":"Cách dùng","value":"Ghi rõ “tương truyền”"}],"objective":"o2","source":"w2","art":"star"}],"sources":[{"key":"w1","title":"Chiến tranh Nguyên Mông – Đại Việt lần 1","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_1","note":"Bản đồ gốc của bài: Chongquannguyenlan1.svg, tác giả Lưu Ly, phạm vi công cộng."},{"key":"w2","title":"Chiến tranh Nguyên Mông – Đại Việt lần 2","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử; Hà Văn Tấn – Phạm Thị Tâm)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_2","note":"Một số chi tiết các nguồn chép khác nhau; nội dung chỉ dùng phần các nguồn thống nhất."},{"key":"manhghep","title":"Trận thủy chiến Bạch Đằng: Những mảnh ghép","publisher":"Bảo tàng Lịch sử quốc gia (đăng lại từ Tia Sáng)","url":"https://baotanglichsu.vn/VI/Articles/3096/71341/tran-thuy-chien-bach-djang-nhung-manh-ghep.html","note":"Tổng hợp kết quả khảo cổ các bãi cọc Yên Giang, Đồng Vạn Muối, Đồng Má Ngựa."},{"key":"wthd","title":"Trần Hưng Đạo","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư)","url":"https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_H%C6%B0ng_%C4%90%E1%BA%A1o","note":null}],"explore":null,"battle":null,"debrief":{"title":"Đọc sử như một sử quan","paragraphs":["Những câu nói như lời Trần Thủ Độ (1258), tiếng hô “Đánh!” ở Diên Hồng (1285) hay đoạn Toàn thư chép trận Bạch Đằng (1288) cho thấy ý chí và cách đánh của quân dân Đại Việt.","Có những chuyện chỉ là tương truyền (như chuyện Thoát Hoan chui ống đồng) hoặc các nguồn chép khác nhau. Khi tranh biện, em nên nói rõ nguồn và không khẳng định điều các nguồn chưa thống nhất."],"sources":["w1","w2","manhghep","wthd"],"fiction":"Chặng này chỉ dùng tư liệu đã có nguồn trong các chặng trước; các tình huống tranh biện là phần sáng tạo của trò chơi."},"order":{"by":"Lời dẫn","text":"Kho sử của hội đồng còn giữ những lời nói, câu thơ của người xưa. Em đọc kỹ từng tư liệu rồi dùng chúng để tranh biện."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 25/11/2026 (bốn chiến dịch theo khối): dữ kiện đối chiếu với các bài Wikipedia tiếng Việt “Trận Bạch Đằng (938)”, “Ngô Quyền” và các thẻ, tư liệu đã kiểm chứng của migration 066. Cần giáo viên Lịch sử rà soát lại.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$g9-tl-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Câu “Đầu thần chưa rơi xuống đất, bệ hạ đừng lo gì khác” cho thấy điều gì?$hq$, $hq${"options":[{"id":"a","text":"Quyết tâm kháng chiến đến cùng"},{"id":"b","text":"Thái sư muốn xin hàng"},{"id":"c","text":"Triều đình đã hết quân"},{"id":"d","text":"Vua sắp sang đất Tống"}],"correct":"a"}$hq$::jsonb, $hq$Trần Thủ Độ tâu như vậy khi có người khuyên vua lánh sang đất Tống, giữ vững quyết tâm đánh giặc của triều đình năm 1258.$hq$, $hq$w1$hq$),
    ($hq$g9-tl-q2$hq$, 2, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Đoạn “Nhân lúc nước triều lên… Nước triều xuống, thuyền giặc vướng cọc hết” chép về trận nào?$hq$, $hq${"options":[{"id":"a","text":"Trận Bạch Đằng năm 1288"},{"id":"b","text":"Trận Đông Bộ Đầu năm 1258"},{"id":"c","text":"Trận Hàm Tử năm 1285"},{"id":"d","text":"Trận Vân Đồn năm 1288"}],"correct":"a"}$hq$::jsonb, $hq$Đại Việt sử ký toàn thư chép như vậy về trận Bạch Đằng năm 1288 do Hưng Đạo vương chỉ huy.$hq$, $hq$manhghep$hq$),
    ($hq$g9-tl-p1$hq$, 3, $hq$pairs$hq$, $hq$practice$hq$, $hq$o1$hq$, $hq$Lật thẻ và ghép mỗi câu với người đã nói hoặc viết.$hq$, $hq${"left_label":"Câu","right_label":"Người","pairs":[{"id":"p1","left":"“Đầu thần chưa rơi xuống đất…”","right":"Trần Thủ Độ"},{"id":"p2","left":"“Ta thà làm ma nước Nam…”","right":"Trần Bình Trọng"},{"id":"p3","left":"“Đoạt sáo Chương Dương độ…”","right":"Trần Quang Khải"},{"id":"p4","left":"“Xã tắc hai phen bon ngựa đá…”","right":"Trần Nhân Tông"}]}$hq$::jsonb, $hq$Bốn câu của bốn nhân vật: Thái sư Trần Thủ Độ (1258), Trần Bình Trọng (1285), Trần Quang Khải (bài thơ năm 1285) và vua Trần Nhân Tông.$hq$, $hq$w2$hq$),
    ($hq$g9-tl-q3$hq$, 4, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Lời dặn “Khoan thư sức dân để làm kế sâu rễ bền gốc” của Trần Hưng Đạo khuyên điều gì?$hq$, $hq${"options":[{"id":"a","text":"Nới sức dân, chăm lo cho dân thì đất nước mới bền"},{"id":"b","text":"Tăng thuế để có nhiều lương thực"},{"id":"c","text":"Bắt dân đi lính thật nhiều"},{"id":"d","text":"Xây thật nhiều thành lũy"}],"correct":"a"}$hq$::jsonb, $hq$“Khoan thư sức dân” là nới sức dân; dân yên thì gốc nước mới vững, đó là “thượng sách giữ nước”.$hq$, $hq$wthd$hq$),
    ($hq$g9-tl-t1$hq$, 5, $hq$tactic$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Em trả lời bạn thế nào?$hq$, $hq${"situation":"Một bạn nói: “Chuyện Thoát Hoan chui vào ống đồng để trốn về nước chắc chắn là thật.”","options":[{"id":"a","text":"Đó là chuyện tương truyền, khi kể phải nói rõ là “tương truyền”","feedback":"Đúng: nguồn chép đây là chuyện tương truyền, không phải sự thật chắc chắn.","score":2},{"id":"b","text":"Bỏ chuyện đó đi vì không quan trọng","feedback":"Không cần bỏ, chỉ cần nói rõ đó là chuyện tương truyền.","score":1},{"id":"c","text":"Đúng vậy, sách nào cũng chép như thế","feedback":"Chưa đúng: đây chỉ là chuyện tương truyền.","score":0}]}$hq$::jsonb, $hq$Khi dùng sử liệu cần phân biệt điều chắc chắn với chuyện tương truyền.$hq$, $hq$w2$hq$),
    ($hq$g9-tl-t2$hq$, 6, $hq$tactic$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Em làm gì khi viết bài?$hq$, $hq${"situation":"Em thấy hai nguồn ghi số quân Nguyên năm 1285 khác nhau.","options":[{"id":"a","text":"Ghi cả hai con số và nói rõ nguồn nào chép, không khẳng định một số","feedback":"Đúng cách làm của người viết sử: nêu nguồn, không tự khẳng định.","score":2},{"id":"b","text":"Chọn số lớn nhất cho bài thêm hấp dẫn","feedback":"Chọn số theo ý thích là làm sai lệch lịch sử.","score":0},{"id":"c","text":"Lấy trung bình hai con số","feedback":"Con số tự tính ra không có nguồn nào chép.","score":0}]}$hq$::jsonb, $hq$Khi các nguồn chép khác nhau, hãy ghi rõ từng nguồn và không khẳng định điều chưa thống nhất.$hq$, $hq$w2$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$tu-lieu-tranh-bien$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- Khối 9 · Thử thách lịch sử (Nếu… thì…)
INSERT INTO public.hk_saga_stages (code, campaign_no, grade, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$thu-thach-lich-su$hq$, NULL, 9, 18, $hq$Thử thách lịch sử$hq$, $hq$Đại Việt$hq$, $hq$Nếu… thì…$hq$, $hq$council$hq$, $hq$target$hq$, $hq$Chế độ “Nếu… thì…”: suy luận chuyện gì có thể xảy ra nếu người xưa chọn khác, rồi so với điều đã thật sự xảy ra; rút ra bài học giữ nước hôm nay.$hq$, 0.5, 0.5, NULL, NULL, $hq$tu-lieu-tranh-bien$hq$, 70, 200, 80, NULL, NULL,
     $hq${"objectives":[{"id":"o1","text":"Suy luận được hệ quả của những lựa chọn khác trong lịch sử dựa trên hiểu biết về nguyên nhân – kết quả."},{"id":"o2","text":"Rút ra được bài học giữ nước từ ba lần kháng chiến cho hôm nay."}],"cards":[{"id":"c1","kind":"why","title":"Con nước phải đúng giờ","body":"Kế bãi cọc chỉ thành khi dụ được thuyền giặc tới đúng bãi cọc lúc nước triều còn cao, rồi triều mới rút. Nếu triều rút quá sớm, cọc lộ ra và thuyền giặc tránh được; nếu quá muộn, thuyền giặc vượt qua bãi cọc.","facts":[{"label":"Điều kiện","value":"Nhử đúng chỗ, đúng giờ"}],"objective":"o1","source":"w938","art":"river"},{"id":"c2","kind":"how","title":"Lương quyết định sức giặc","body":"Đạo quân Nguyên rất đông, trông cả vào lương chở bằng thuyền. Khi đoàn thuyền lương bị đánh tan ở Vân Đồn, giặc phải bỏ Thăng Long về Vạn Kiếp rồi tính đường rút.","facts":[{"label":"Bước ngoặt","value":"Trận Vân Đồn"}],"objective":"o1","source":"w3","art":"granary"},{"id":"c3","kind":"who","title":"Một lời giữ cả triều đình","body":"Năm 1258, Thái úy Trần Nhật Hiệu viết hai chữ “nhập Tống” (sang lánh đất Tống), còn Thái sư Trần Thủ Độ tâu: “Đầu thần chưa rơi xuống đất, bệ hạ đừng lo gì khác.” Triều đình ở lại kháng chiến.","facts":[{"label":"Lựa chọn","value":"Ở lại đánh giặc"}],"objective":"o1","source":"w1","art":"scroll"},{"id":"c4","kind":"why","title":"Gốc của giữ nước","body":"Trần Hưng Đạo dặn vua: “Khoan thư sức dân để làm kế sâu rễ bền gốc, đó là thượng sách giữ nước vậy.” Sức mạnh giữ nước bắt đầu từ lòng dân.","facts":[{"label":"Thượng sách","value":"Khoan thư sức dân"}],"objective":"o2","source":"wthd","art":"crowd"}],"sources":[{"key":"w938","title":"Trận Bạch Đằng (938)","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư)","url":"https://vi.wikipedia.org/wiki/Tr%E1%BA%ADn_B%E1%BA%A1ch_%C4%90%E1%BA%B1ng_(938)","note":"Các nguồn chép khác nhau về quân số của quân ta; nội dung chỉ dùng phần các nguồn thống nhất."},{"key":"w1","title":"Chiến tranh Nguyên Mông – Đại Việt lần 1","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_1","note":"Bản đồ gốc của bài: Chongquannguyenlan1.svg, tác giả Lưu Ly, phạm vi công cộng."},{"key":"w3","title":"Chiến tranh Nguyên Mông – Đại Việt lần 3","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử, Khâm định Việt sử thông giám cương mục)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_3","note":null},{"key":"wthd","title":"Trần Hưng Đạo","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư)","url":"https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_H%C6%B0ng_%C4%90%E1%BA%A1o","note":null}],"explore":null,"battle":{"mode":"council","style":"whatif","title":"Thử thách “Nếu… thì…”","intro":"Bốn thử thách suy luận. Chọn hệ quả hợp lý nhất, rồi xem điều đã thật sự xảy ra. Lập luận chắc chắn thì thanh “Lập luận” tăng.","cast":[{"id":"suquan","name":"Sử quan","role":"Nhân vật hư cấu","fictional":true}],"meters":[{"id":"lap_luan","label":"Lập luận","start":30,"win":70}],"rounds":[{"id":"r1","who":"Sử quan","ask":"Nếu năm 1258 triều Trần nghe theo hai chữ “nhập Tống”, bỏ nước sang đất Tống, điều gì dễ xảy ra?","label":"Nếu “nhập Tống” (1258)","history":"Thực tế: Trần Thủ Độ tâu “Đầu thần chưa rơi xuống đất, bệ hạ đừng lo gì khác”; triều đình ở lại kháng chiến và thắng ở Đông Bộ Đầu.","options":[{"id":"a","tag":"Suy luận","text":"Kháng chiến mất người lãnh đạo, giặc dễ chiếm cả nước","say":null,"reply":"Lập luận chặt: không có triều đình đứng đầu thì khó tập hợp quân dân.","score":2,"effect":{"lap_luan":15}},{"id":"b","tag":"Suy luận","text":"Không sao, quân dân vẫn tự đánh thắng như thường","say":null,"reply":"Chưa chặt: thiếu người lãnh đạo thì các nơi khó phối hợp.","score":0,"effect":{"lap_luan":-5}},{"id":"c","tag":"Suy luận","text":"Nhà Tống sẽ đem quân sang đánh đuổi quân Mông Cổ giúp","say":null,"reply":"Không có căn cứ nào cho thấy điều đó.","score":0,"effect":{"lap_luan":-5}}]},{"id":"r2","who":"Sử quan","ask":"Nếu đoàn thuyền lương của Trương Văn Hổ tới nơi an toàn, quân Nguyên sẽ ra sao?","label":"Nếu không có Vân Đồn (1288)","history":"Thực tế: đoàn thuyền lương bị đánh tan ở Vân Đồn; Thoát Hoan thiếu lương, phải bỏ Thăng Long về Vạn Kiếp rồi rút quân.","options":[{"id":"a","tag":"Suy luận","text":"Giặc đủ lương, giữ Thăng Long lâu hơn, ta khó đánh hơn","say":null,"reply":"Đúng hướng: lương là chỗ dựa để giặc đánh lâu dài.","score":2,"effect":{"lap_luan":15}},{"id":"b","tag":"Suy luận","text":"Giặc vẫn phải rút ngay như cũ","say":null,"reply":"Chưa hợp lý: giặc rút chính vì thiếu lương.","score":0,"effect":{"lap_luan":-5}},{"id":"c","tag":"Suy luận","text":"Chẳng có gì khác","say":null,"reply":"Mất lương là bước ngoặt, nên đổi một điều thì đổi nhiều điều.","score":0,"effect":{"lap_luan":-5}}]},{"id":"r3","who":"Sử quan","ask":"Ở trận Bạch Đằng, nếu nước triều rút trước khi thuyền giặc vào tới bãi cọc thì sao?","label":"Nếu triều rút sớm","history":"Thực tế (938 và 1288): quân ta nhử giặc vào bãi cọc lúc nước triều còn cao; khi thuyền giặc đã ở trên bãi cọc, triều mới rút.","options":[{"id":"a","tag":"Suy luận","text":"Bãi cọc lộ ra sớm, thuyền giặc thấy và tránh được","say":null,"reply":"Đúng: vì vậy phải tính con nước theo từng giờ.","score":2,"effect":{"lap_luan":15}},{"id":"b","tag":"Suy luận","text":"Thuyền giặc vẫn mắc cọc như thường","say":null,"reply":"Chưa đúng: cọc lộ ra thì giặc đã biết mà tránh.","score":0,"effect":{"lap_luan":-5}},{"id":"c","tag":"Suy luận","text":"Quân ta không cần nhử giặc nữa","say":null,"reply":"Không nhử thì giặc không vào bãi cọc.","score":0,"effect":{"lap_luan":-5}}]},{"id":"r4","who":"Sử quan","ask":"Theo em, bài học nào của ba lần kháng chiến còn đúng với hôm nay?","label":"Bài học hôm nay","history":"Trần Hưng Đạo dặn: “Khoan thư sức dân để làm kế sâu rễ bền gốc, đó là thượng sách giữ nước vậy.”","options":[{"id":"a","tag":"Bài học","text":"Đoàn kết, chăm lo sức dân và hiểu rõ đất nước mình","say":null,"reply":"Đó là điều làm nên chiến thắng cả ba lần.","score":2,"effect":{"lap_luan":15}},{"id":"b","tag":"Bài học","text":"Chỉ cần vũ khí thật mạnh là đủ","say":null,"reply":"Ba lần kháng chiến cho thấy lòng dân và kế sách mới là gốc.","score":0,"effect":{"lap_luan":-5}},{"id":"c","tag":"Bài học","text":"Mỗi người tự lo cho mình","say":null,"reply":"Ngược với tinh thần Diên Hồng.","score":0,"effect":{"lap_luan":-5}}]}],"tips":["Không có đáp án “đúng như lịch sử” cho câu hỏi “nếu… thì…”: hãy chọn suy luận có căn cứ nhất từ các thẻ Binh thư."],"win_text":"Lập luận vững vàng! Em đã hiểu vì sao mỗi lựa chọn của người xưa dẫn tới kết quả như lịch sử đã chép.","lose_text":"Lập luận chưa vững. Hãy đọc lại các thẻ Binh thư: nguyên nhân nào dẫn tới kết quả nào."},"debrief":{"title":"Nếu… thì… và bài học giữ nước","paragraphs":["Ba lần kháng chiến cho thấy nhiều kết quả phụ thuộc vào những lựa chọn đúng lúc: triều đình ở lại kháng chiến năm 1258, đánh vào lương giặc ở Vân Đồn, tính đúng con nước ở Bạch Đằng.","Câu hỏi “nếu… thì…” không làm thay đổi lịch sử, nhưng giúp em hiểu nguyên nhân – kết quả. Bài học còn nguyên giá trị là lời dặn của Trần Hưng Đạo: “khoan thư sức dân” là thượng sách giữ nước."],"sources":["w938","w1","w3","wthd"],"fiction":"Các câu hỏi “nếu… thì…” là suy luận giả định của trò chơi, không phải sự kiện lịch sử; dòng “Thực tế” của mỗi lượt lấy từ nguồn ghi bên dưới."},"order":{"by":"Lời dẫn","text":"Thử thách cuối cùng của Nguyên soái: suy luận “nếu… thì…” từ những gì em đã học, rồi đối chiếu với lịch sử thật."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 25/11/2026 (bốn chiến dịch theo khối): dữ kiện đối chiếu với các bài Wikipedia tiếng Việt “Trận Bạch Đằng (938)”, “Ngô Quyền” và các thẻ, tư liệu đã kiểm chứng của migration 066. Cần giáo viên Lịch sử rà soát lại.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$g9-tt-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Vì sao kế bãi cọc chỉ thành công khi tính đúng con nước?$hq$, $hq${"options":[{"id":"a","text":"Phải dụ thuyền giặc vào bãi cọc lúc triều cao rồi triều mới rút"},{"id":"b","text":"Vì cọc chỉ cắm được vào ban đêm"},{"id":"c","text":"Vì thuyền giặc chỉ đi khi trời mưa"},{"id":"d","text":"Vì quân ta chỉ đánh được khi triều lên"}],"correct":"a"}$hq$::jsonb, $hq$Triều rút sớm thì cọc lộ và giặc tránh được; rút muộn thì thuyền giặc vượt qua bãi cọc.$hq$, $hq$w938$hq$),
    ($hq$g9-tt-t1$hq$, 2, $hq$tactic$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Em suy luận thế nào?$hq$, $hq${"situation":"Nếu năm 1288 quân Trần không đánh đoàn thuyền lương ở Vân Đồn thì quân Nguyên ở Thăng Long sẽ thế nào?","options":[{"id":"a","text":"Đủ lương nên giữ thành lâu hơn, quân ta khó đánh hơn","feedback":"Hợp lý: chính việc mất lương buộc giặc phải rút.","score":2},{"id":"b","text":"Vẫn rút sớm như cũ","feedback":"Chưa hợp lý: giặc rút vì thiếu lương.","score":0},{"id":"c","text":"Sẽ đầu hàng ngay","feedback":"Không có căn cứ.","score":0}]}$hq$::jsonb, $hq$Trận Vân Đồn là bước ngoặt: mất lương, quân Nguyên rơi vào thế bị động rồi phải rút.$hq$, $hq$w3$hq$),
    ($hq$g9-tt-q2$hq$, 3, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Vì sao lời tâu của Trần Thủ Độ năm 1258 rất quan trọng?$hq$, $hq${"options":[{"id":"a","text":"Giữ triều đình ở lại kháng chiến khi có người khuyên sang đất Tống"},{"id":"b","text":"Vì ông chỉ huy trận Bạch Đằng"},{"id":"c","text":"Vì ông ký hòa ước với giặc"},{"id":"d","text":"Vì ông viết Hịch tướng sĩ"}],"correct":"a"}$hq$::jsonb, $hq$Khi Trần Nhật Hiệu viết hai chữ “nhập Tống”, lời của Trần Thủ Độ giữ vững quyết tâm đánh giặc của triều đình.$hq$, $hq$w1$hq$),
    ($hq$g9-tt-s1$hq$, 4, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp chuỗi nguyên nhân – kết quả của lần thứ ba cho đúng.$hq$, $hq${"items":[{"id":"m1","text":"Đoàn thuyền lương bị đánh tan ở Vân Đồn","when":"Cuối 1287 – đầu 1288"},{"id":"m2","text":"Quân Nguyên thiếu lương ở Thăng Long","when":"Tháng 2/1288"},{"id":"m3","text":"Thoát Hoan rút về Vạn Kiếp, quyết định rút quân","when":"Tháng 3/1288"},{"id":"m4","text":"Thủy quân Nguyên bị tiêu diệt ở Bạch Đằng","when":"9/4/1288"}]}$hq$::jsonb, $hq$Mất lương → thiếu ăn → phải rút → bị đón đánh ở Bạch Đằng.$hq$, $hq$w3$hq$),
    ($hq$g9-tt-q3$hq$, 5, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$“Thượng sách giữ nước” theo lời dặn của Trần Hưng Đạo là gì?$hq$, $hq${"options":[{"id":"a","text":"Khoan thư sức dân"},{"id":"b","text":"Xây thành thật cao"},{"id":"c","text":"Tăng quân thật đông"},{"id":"d","text":"Nộp cống cho nước lớn"}],"correct":"a"}$hq$::jsonb, $hq$Trần Hưng Đạo dặn: “Khoan thư sức dân để làm kế sâu rễ bền gốc, đó là thượng sách giữ nước vậy.”$hq$, $hq$wthd$hq$),
    ($hq$g9-tt-t2$hq$, 6, $hq$tactic$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Em chọn bài học nào?$hq$, $hq${"situation":"Lớp em bàn: bài học nào từ ba lần kháng chiến giúp học sinh hôm nay sống tốt hơn với quê hương?","options":[{"id":"a","text":"Biết đoàn kết, cùng nhau góp sức cho việc chung","feedback":"Đúng tinh thần Diên Hồng: cả nước một lòng.","score":2},{"id":"b","text":"Chỉ người lớn mới cần quan tâm việc nước","feedback":"Trần Quốc Toản còn trẻ đã muốn góp sức đánh giặc.","score":0},{"id":"c","text":"Ai giỏi thì tự làm, không cần ai","feedback":"Tài giỏi là tốt, nhưng ba lần thắng đều nhờ đồng lòng.","score":1}]}$hq$::jsonb, $hq$Sự đồng lòng từ triều đình tới nhân dân là điểm chung của cả ba lần chiến thắng.$hq$, $hq$w1$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$thu-thach-lich-su$hq$
ON CONFLICT (code) DO NOTHING;

