INSERT INTO public.hk_saga_stage_versions (stage_id, version, content, status) SELECT id, version, content, status FROM public.hk_saga_stages WHERE code IN ($hq$dien-hong$hq$, $hq$vuon-khong-nha-trong$hq$, $hq$van-kiep-1288$hq$) AND content->'battle' IS NULL ON CONFLICT DO NOTHING;
UPDATE public.hk_saga_stages SET content = jsonb_set(content, '{battle}', $hq${"mode":"council","style":"persuade","title":"Thuyết phục các bô lão","intro":"Thượng hoàng hỏi các bô lão: nên hòa hay nên đánh? Vài bô lão còn lo vì giặc quá đông. Em đưa ra thẻ Binh thư để thuyết phục, làm cho cả điện một lòng.","cast":[{"id":"thuong_hoang","name":"Thượng hoàng Trần Thánh Tông","role":"Người triệu tập hội nghị","fictional":false},{"id":"bl_dongtrieu","name":"Bô lão Đông Triều","role":"Nhân vật hư cấu","fictional":true},{"id":"bl_thientruong","name":"Bô lão Thiên Trường","role":"Nhân vật hư cấu","fictional":true},{"id":"bl_hongchau","name":"Bô lão Hồng Châu","role":"Nhân vật hư cấu","fictional":true}],"meters":[{"id":"dong_long","label":"Đồng lòng kháng chiến","start":40,"win":80}],"rounds":[{"id":"r1","who":"Bô lão Đông Triều","ask":"Giặc Nguyên kéo sang rất đông. E rằng ta nên tính đường hòa?","label":"Giặc mạnh thì sao","history":"Năm 1258 quân Trần đã tập kích, đánh tan quân Mông Cổ ở Đông Bộ Đầu.","options":[{"id":"a","tag":"Chiến công","text":"Năm 1258 ta đã phá quân Mông Cổ ở Đông Bộ Đầu","say":"Năm 1258 giặc Mông Cổ cũng mạnh, vậy mà ta đã đánh úp chúng ở Đông Bộ Đầu.","reply":"Phải! Giặc mạnh mà ta vẫn từng thắng. Lòng người vững hơn rồi.","score":2,"effect":{"dong_long":25}},{"id":"b","tag":"Thế giặc","text":"Quân Nguyên đông gấp bội quân ta","say":"Giặc đông gấp bội quân ta…","reply":"Nghe vậy lão càng lo hơn…","score":0,"effect":{"dong_long":-10}},{"id":"c","tag":"Ngoại giao","text":"Nộp cống thật nhiều để giặc thôi đánh","say":"Hay ta nộp cống cho yên?","reply":"Giặc đã quyết đánh thì nộp cống bao nhiêu cũng không đủ.","score":0,"effect":{"dong_long":-15}}]},{"id":"r2","who":"Bô lão Thiên Trường","ask":"Đánh thì ai đủ tài cầm quân cho cả nước?","label":"Ai cầm quân","history":"Trần Quốc Tuấn được phong Quốc công Tiết chế, thống lĩnh mọi lực lượng của Đại Việt.","options":[{"id":"a","tag":"Người cầm quân","text":"Quốc công Tiết chế Trần Quốc Tuấn thống lĩnh toàn quân","say":"Triều đình đã phong Trần Quốc Tuấn làm Quốc công Tiết chế, thống lĩnh toàn quân.","reply":"Có Hưng Đạo vương cầm quân thì lão yên lòng.","score":2,"effect":{"dong_long":20}},{"id":"b","tag":"Thế trận","text":"Mỗi làng tự đánh lấy, không cần ai chỉ huy","say":"Làng nào tự lo làng nấy.","reply":"Mỗi nơi một kiểu thì sao chống nổi giặc lớn?","score":0,"effect":{"dong_long":-10}},{"id":"c","tag":"Ngoại giao","text":"Chờ nước khác đem quân sang giúp","say":"Hay ta chờ nước khác sang giúp?","reply":"Trông vào người ngoài thì lỡ hết thời cơ.","score":0,"effect":{"dong_long":-15}}]},{"id":"r3","who":"Bô lão Hồng Châu","ask":"Quân sĩ có đủ quyết tâm đánh giặc không?","label":"Tinh thần quân sĩ","history":"Trần Quốc Tuấn viết Hịch tướng sĩ; nhiều chiến sĩ thích hai chữ “Sát Thát” lên cánh tay để tỏ quyết tâm.","options":[{"id":"a","tag":"Ý chí","text":"Hịch tướng sĩ – quân sĩ thích hai chữ “Sát Thát” lên cánh tay","say":"Hưng Đạo vương đã ra Hịch tướng sĩ, quân sĩ thích lên tay hai chữ “Sát Thát”.","reply":"Tướng sĩ một lòng, dân ta cũng một lòng. Xin cho đánh!","score":2,"effect":{"dong_long":25}},{"id":"b","tag":"Thế trận","text":"Quân ta ít, nên giữ sức chờ thời","say":"Quân ta còn ít, ta nên giữ sức.","reply":"Giữ sức là phải, nhưng lòng quân thế nào?","score":1,"effect":{"dong_long":5}},{"id":"c","tag":"Ý chí","text":"Ai muốn về quê thì cứ về","say":"Ai sợ thì cứ về quê.","reply":"Vậy thì ai đánh giặc?","score":0,"effect":{"dong_long":-20}}]}],"tips":["Đọc lại thẻ “Hịch tướng sĩ và Sát Thát”, “Người cầm quân” trước khi đưa thẻ.","Thanh “Đồng lòng” phải đạt 80 sau lượt cuối."],"win_text":"Muôn người như một: “Đánh!”. Đại Việt sử ký toàn thư chép các bô lão “vạn người cùng nói như từ một miệng”.","lose_text":"Điện Diên Hồng còn chưa một lòng. Hãy đưa ra những thẻ cho thấy ta có chiến công, có người cầm quân và quân sĩ quyết tâm."}$hq$::jsonb), version = version + 1, updated_at = now()
    WHERE code = $hq$dien-hong$hq$ AND (content->'battle' IS NULL OR jsonb_typeof(content->'battle') = 'null');
UPDATE public.hk_saga_stages SET content = jsonb_set(content, '{battle}', $hq${"mode":"council","style":"command","title":"Sơ tán dân, giấu lương kịp giờ","intro":"Kỵ binh Mông Cổ sắp tới Thăng Long. Em giúp triều đình quyết định ba việc gấp: lương thực, kinh thành và đường đi của triều đình.","cast":[{"id":"thu_do","name":"Thái sư Trần Thủ Độ","role":"Thái sư nhà Trần","fictional":false},{"id":"xa_truong","name":"Ông xã trưởng","role":"Nhân vật hư cấu","fictional":true}],"meters":[{"id":"luong","label":"Lương không về tay giặc","start":30,"win":70},{"id":"luc","label":"Lực lượng được giữ","start":40,"win":70}],"rounds":[{"id":"r1","who":"Ông xã trưởng","ask":"Lệnh triều đình đã về. Kho thóc của làng nên làm thế nào?","label":"Lương thực trong làng","history":"Triều Trần sớm ra lệnh cho nhân dân cất giấu lương thực; quân Mông Cổ cướp lương quanh vùng không được bao nhiêu.","options":[{"id":"a","tag":"Kế sách","text":"Cất giấu hết lương thực, không để lại cho giặc","say":null,"reply":"Giặc đến mà không có gì để ăn!","score":2,"effect":{"luong":45}},{"id":"b","tag":"Kế sách","text":"Để nguyên kho mà đi cho nhanh","say":null,"reply":"Giặc sẽ có lương mà đánh lâu.","score":0,"effect":{"luong":-10}},{"id":"c","tag":"Kế sách","text":"Gánh theo hết dù phải đi chậm","say":null,"reply":"Giữ được lương nhưng dân đi chậm, dễ gặp giặc.","score":1,"effect":{"luong":20,"luc":-5}}]},{"id":"r2","who":"Thái sư Trần Thủ Độ","ask":"Thua trận Phù Lỗ, giặc đang tiến về kinh thành. Ta giữ thành hay rời đi?","label":"Kinh thành Thăng Long","history":"Sau trận Phù Lỗ (18/1/1258), quân Trần chủ động rời Thăng Long; quân Mông Cổ vào kinh thành nhưng kho tàng trống rỗng.","options":[{"id":"a","tag":"Kế sách","text":"Rời kinh thành, giữ thuyền và lực lượng","say":null,"reply":"Giặc vào thành trống, còn ta vẫn còn quân.","score":2,"effect":{"luc":35}},{"id":"b","tag":"Kế sách","text":"Giữ thành đến người cuối cùng","say":null,"reply":"Kỵ binh giặc đang mạnh, giữ thành là mất quân.","score":0,"effect":{"luc":-25}},{"id":"c","tag":"Ngoại giao","text":"Mở cửa thành mời giặc vào để xin hòa","say":null,"reply":"Giặc vào thành sẽ cướp sạch, dân càng khổ.","score":0,"effect":{"luong":-20,"luc":-10}}]},{"id":"r3","who":"Thái sư Trần Thủ Độ","ask":"Trên thuyền ở sông Thiên Mạc, có người viết hai chữ “nhập Tống”, khuyên vua sang lánh đất Tống. Em theo ý nào?","label":"Lời bàn trên sông Thiên Mạc","history":"Thái sư Trần Thủ Độ tâu: “Đầu thần chưa rơi xuống đất, bệ hạ đừng lo gì khác.” Triều đình ở lại kháng chiến.","options":[{"id":"a","tag":"Ý chí","text":"Ở lại đánh giặc như lời Thái sư Trần Thủ Độ","say":null,"reply":"“Đầu thần chưa rơi xuống đất, bệ hạ đừng lo gì khác!”","score":2,"effect":{"luc":20,"luong":5}},{"id":"b","tag":"Kế sách","text":"Sang đất Tống lánh nạn","say":null,"reply":"Vua bỏ nước thì ai giữ nước?","score":0,"effect":{"luc":-20}},{"id":"c","tag":"Kế sách","text":"Chia nhau về quê, ai lo phần nấy","say":null,"reply":"Quân tan thì không còn ngày phản công.","score":0,"effect":{"luc":-25}}]}],"tips":["Cả hai thanh “Lương không về tay giặc” và “Lực lượng được giữ” phải đạt 70."],"win_text":"Quân Mông Cổ vào một kinh thành trống, không cướp được lương. Quân Trần còn nguyên lực lượng, chờ thời cơ phản công.","lose_text":"Giặc còn lương hoặc ta mất quá nhiều quân. Nhớ lại: cất giấu lương, rời kinh thành, giữ vững ý chí."}$hq$::jsonb), version = version + 1, updated_at = now()
    WHERE code = $hq$vuon-khong-nha-trong$hq$ AND (content->'battle' IS NULL OR jsonb_typeof(content->'battle') = 'null');
UPDATE public.hk_saga_stages SET content = jsonb_set(content, '{battle}', $hq${"mode":"council","style":"command","title":"Cắt lương, dồn giặc vào thế phải rút","intro":"Quân Nguyên lại vào Thăng Long nhưng thiếu lương rồi co cụm ở Vạn Kiếp. Em giúp Hưng Đạo vương quyết định từng bước để giặc kiệt sức.","cast":[{"id":"hung_dao","name":"Hưng Đạo vương Trần Quốc Tuấn","role":"Quốc công Tiết chế","fictional":false},{"id":"tham_tu","name":"Người do thám","role":"Nhân vật hư cấu","fictional":true}],"meters":[{"id":"the","label":"Thế của ta","start":30,"win":80}],"rounds":[{"id":"r1","who":"Người do thám","ask":"Đầu tháng 2/1288, quân Nguyên đánh tới Thăng Long. Ta làm gì?","label":"Giặc vào Thăng Long","history":"Quân Nguyên vào được kinh thành nhưng thiếu lương, không bắt được hai vua Trần và không phá được chủ lực quân Đại Việt.","options":[{"id":"a","tag":"Kế sách","text":"Để giặc vào kinh thành trống, giữ chủ lực ở ngoài","say":null,"reply":"Giặc chiếm thành mà không thắng được ta.","score":2,"effect":{"the":15}},{"id":"b","tag":"Kế sách","text":"Dồn hết chủ lực ra giữ kinh thành","say":null,"reply":"Đối đầu lúc giặc còn đông là thiệt quân.","score":0,"effect":{"the":-15}},{"id":"c","tag":"Ngoại giao","text":"Xin hòa để giặc rút","say":null,"reply":"Giặc chưa kiệt sức thì chưa chịu rút.","score":0,"effect":{"the":-10}}]},{"id":"r2","who":"Người do thám","ask":"Thoát Hoan bỏ Thăng Long về Vạn Kiếp, co cụm trong các thành gỗ. Ta làm gì?","label":"Giặc ở Vạn Kiếp","history":"Ở Vạn Kiếp, quân Nguyên lương ít, đêm đêm bị tập kích, bệnh tật lan rộng.","options":[{"id":"a","tag":"Thế giặc","text":"Tập kích ban đêm liên tục, không cho giặc yên","say":null,"reply":"Giặc ngày đói, đêm không ngủ được.","score":2,"effect":{"the":20}},{"id":"b","tag":"Thế trận","text":"Đánh thẳng vào thành gỗ giữa ban ngày","say":null,"reply":"Đánh vào chỗ giặc phòng bị chắc là thiệt cho ta.","score":0,"effect":{"the":-10}},{"id":"c","tag":"Thế trận","text":"Để yên cho giặc nghỉ","say":null,"reply":"Giặc nghỉ thì lại hồi sức.","score":0,"effect":{"the":-10}}]},{"id":"r3","who":"Hưng Đạo vương Trần Quốc Tuấn","ask":"Giặc đang nghi ngờ, canh phòng ngày đêm. Làm sao cho chúng mất cảnh giác?","label":"Làm giặc lơi lỏng","history":"Vua Trần dùng kế trá hàng: Hưng Ninh vương Trần Tung sang trại giặc hẹn ngày “xin hàng”, rồi quân Đại Việt bất ngờ tập kích.","options":[{"id":"a","tag":"Kế sách","text":"Sai người sang hẹn ngày “xin hàng” rồi bất ngờ tập kích","say":null,"reply":"Giặc tưởng thật, án binh chờ đợi.","score":2,"effect":{"the":15}},{"id":"b","tag":"Ngoại giao","text":"Xin hòa thật","say":null,"reply":"Bỏ dở lúc giặc sắp kiệt sức thì uổng công.","score":0,"effect":{"the":-15}},{"id":"c","tag":"Kế sách","text":"Gửi thư thách giặc ra đánh","say":null,"reply":"Giặc chưa chắc đã ra, lại càng cảnh giác.","score":1,"effect":{"the":5}}]},{"id":"r4","who":"Hưng Đạo vương Trần Quốc Tuấn","ask":"Cuối tháng 3/1288, tướng Nguyên bàn: “Quân có thể về, không thể giữ.” Giặc sẽ rút theo hai đường thủy, bộ. Ta làm gì?","label":"Giặc quyết rút","history":"Trần Hưng Đạo đoán được và tổ chức đón đánh trên cả hai đường; trận quyết định diễn ra trên sông Bạch Đằng.","options":[{"id":"a","tag":"Địa thế","text":"Đón đánh cả hai đường, chuẩn bị trận địa ở Bạch Đằng","say":null,"reply":"Lần này giặc không về lành lặn được nữa.","score":2,"effect":{"the":20}},{"id":"b","tag":"Địa thế","text":"Chỉ chặn đường bộ","say":null,"reply":"Thủy quân giặc sẽ theo sông ra biển.","score":1,"effect":{"the":5}},{"id":"c","tag":"Thế trận","text":"Để giặc rút êm","say":null,"reply":"Giặc còn sức thì còn quay lại.","score":0,"effect":{"the":-15}}]}],"tips":["Thanh “Thế của ta” phải đạt 80 sau lượt cuối."],"win_text":"Giặc đói, mệt và mất cảnh giác. Thoát Hoan quyết định rút quân, còn quân Trần đã sẵn sàng đón đánh trên sông Bạch Đằng.","lose_text":"Giặc còn sức hoặc rút êm được. Hãy làm giặc kiệt sức từng bước rồi chặn cả hai đường rút."}$hq$::jsonb), version = version + 1, updated_at = now()
    WHERE code = $hq$van-kiep-1288$hq$ AND (content->'battle' IS NULL OR jsonb_typeof(content->'battle') = 'null');

-- ---------------------------------------------------------------------- Khối 7 – 8: mỗi khối 24 câu Hội đồng; các câu dưới đây chỉ còn dùng ở ôn tập
UPDATE public.hk_saga_items SET usage = 'review' WHERE code IN ($hq$s04-p1$hq$, $hq$s04-q3$hq$, $hq$s05-p1$hq$, $hq$s05-q3$hq$, $hq$s06-p1$hq$, $hq$s06-q2$hq$, $hq$s07-p1$hq$, $hq$s07-q3$hq$, $hq$s08-p1$hq$, $hq$s08-q2$hq$, $hq$s09-p1$hq$, $hq$s09-q2$hq$, $hq$s13-p1$hq$);

-- Kho dữ liệu đã xóa (migration 052): bảng mới cũng được gắn trigger lưu trước khi xóa
SELECT public.app_install_delete_archives();
